// Your shop's public address and how prices read.
const STORE_URL = 'https://your-store.com';
const PRICE = (amount) => `From $${amount}`;

// The product's facts for the caption, its page and up to 4 photos (more than one makes a carousel).
const product = $json;
const description = (product.body_html || '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ')
  .replace(/ ([.,!?;:])/g, '$1')
  .trim()
  .slice(0, 1500);
const prices = (product.variants || []).map((v) => Number(v.price)).filter((n) => !Number.isNaN(n));
return {
  json: {
    title: product.title,
    handle: product.handle,
    type: product.product_type || '',
    description,
    price: prices.length ? PRICE(Math.min(...prices).toFixed(2)) : '',
    url: `${STORE_URL}/products/${product.handle}`,
    photos: (product.images || []).map((image) => image.src).filter(Boolean).slice(0, 4).join(','),
  },
};

